mapper.select:
SELECT id, definition_id, base_version_id, revision, content::text,
       published_version_id, published_definition_revision, updated_at
  FROM nw_skill_editing_drafts
 WHERE definition_id=#{definitionId}
   AND tenant_id IS NOT DISTINCT FROM #{tenantId,jdbcType=BIGINT}
 ORDER BY updated_at DESC, id DESC LIMIT 1

SELECT id FROM nw_capability_definitions
 WHERE id=#{id} AND tenant_id IS NOT DISTINCT FROM #{tenantId,jdbcType=BIGINT}
   AND capability_type='SKILL' FOR UPDATE

mapper.update:
UPDATE nw_skill_editing_drafts SET content=#{content}::jsonb, revision=revision+1, updated_at=now(),
       base_version_id=COALESCE(published_version_id,base_version_id),
       published_version_id=NULL, published_definition_revision=NULL
 WHERE id=#{id} AND tenant_id IS NOT DISTINCT FROM #{tenantId,jdbcType=BIGINT}
   AND revision=#{revision}

UPDATE nw_skill_editing_drafts SET content=#{content}::jsonb, base_version_id=#{baseVersionId},
       revision=revision+1, updated_at=now(), published_version_id=NULL, published_definition_revision=NULL
 WHERE id=#{id} AND tenant_id IS NOT DISTINCT FROM #{tenantId,jdbcType=BIGINT}
   AND revision=#{revision}
